{
  "judgements": [
    {
      "claim_id": "cl-fbf17df26de7",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period", "metric", "result"],
      "reason": "前半句「图1：2023年分品种销量（万吨） 图2：2023年分下游销量占比」是图表标题，但后半句「公司紧盯战略客户和国家重大标志性工程……拓展高端客户群」说的是公司自己的营销动作，属于实质经营表述；不过只有对象（战略客户、国家重大标志性工程、高端客户群）和动作，没有期间、指标和结果，且「周到细致的优质服务」「推进营销渠道与客户资源升级」偏套话式表述，但整体有可指向的公司行为，故不判套话。"
    },
    {
      "claim_id": "cl-06f3748a4c43",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "「公司品种钢销量不断提升，占比已由2016年的32%增加到2024年的65%」有对象（品种钢销量占比）、期间（2016年到2024年）、指标（占比）、结果（32%到65%），是公司自身经营数据，实质表述。"
    },
    {
      "claim_id": "cl-90fcfe6228f2",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period", "metric", "result"],
      "reason": "前半句「图1：2024年分品种销量（万吨） 图2：2024年分下游销量占比」是图表标题，后半句「公司紧盯战略客户和国家重大标志性工程……拓展高端客户群」说的是公司自己的营销动作，属于实质经营表述；但只有对象和动作，没有期间、指标和结果，且「周到细致的优质服务」「推进营销渠道与客户资源升级」偏套话式表述，但整体有可指向的公司行为，故不判套话。"
    },
    {
      "claim_id": "cl-01d530227f9e",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "「华菱涟钢已经积累了成熟的电工钢生产经验与理论基础，在取向电工钢基料供应方面已实现普通取向、升级版取向、高磁感取向原料系列牌号全覆盖，2022年取向硅钢基料产销量超40万吨」有主体（华菱涟钢）、对象（取向电工钢基料）、期间（2022年）、指标（产销量）、结果（超40万吨、全覆盖），是实质经营表述。"
    },
    {
      "claim_id": "cl-b875a18f4dd4",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["owner"],
      "reason": "「2023年取向硅钢基料销量达57.42万吨，创造新的纪录」有期间（2023年）、对象（取向硅钢基料）、指标（销量）、结果（57.42万吨），是实质经营数据；未明确写出责任主体，但结合上下文可指向公司，此处按字面标缺 owner。"
    },
    {
      "claim_id": "cl-bed6bc69f604",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period"],
      "reason": "「全年开发特厚齿条钢、管坯用钢、高强车轮钢、高锰无磁钢、高强度气瓶管等新品种180多项，新增30个钢种『替代进口』，重点品种钢销量占比增至63%，较2022年再提升3个百分点」有对象（新品种、重点品种钢）、指标（品种数、占比）、结果（180多项、30个、63%、提升3个百分点），是实质经营表述；只写「全年」未明确年份，故标缺 period。"
    },
    {
      "claim_id": "cl-f9aea64dc748",
      "is_substantive": false,
      "is_template": false,
      "missing_elements": ["object", "metric", "result", "owner"],
      "reason": "「2024年，钢铁行业持续深度调整，行业运行呈现高产量、高成本、高出口、低需求、低价格、低效益的『三高三低』局面，行业供需矛盾突出……」说的是钢铁行业整体形势，不是这家公司自身干了什么，属于一般背景介绍与行业综述，故 is_substantive=false；因是行业描述而非套话，is_template 仍为 false。"
    },
    {
      "claim_id": "cl-f7f92a0f02c7",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period", "owner"],
      "reason": "「重点品种钢销量1,588万吨，占比60%，较2021年提升5个百分点」有对象（重点品种钢）、指标（销量、占比）、结果（1,588万吨、60%、提升5个百分点），是实质经营数据；未明确写出本期年份，也未明确责任主体，故标缺 period 和 owner。"
    }
  ]
}
